# --- AI Vision ---

def find_cone():
    """Largest 'cone' colour code in view, else a yellow blob beside a blue one, or None."""
    largest = None
    largest_area = 0

    for obj in ai_vision.take_snapshot(AiVision.ALL_CODES, VISION_MAX_OBJECTS):
        if obj.id != CONE_CODE_ID:
            continue
        if obj.width < VISION_MIN_WIDTH or obj.height < VISION_MIN_HEIGHT:
            continue
        area = obj.width * obj.height
        if area > largest_area:
            largest = obj
            largest_area = area

    if largest is not None:
        return largest
    return find_color_pair()

class ConeBox:
    """Bounding box with the AiVisionObject fields the cone code reads."""
    def __init__(self, left, top, right, bottom):
        self.width = right - left
        self.height = bottom - top
        self.centerX = (left + right) // 2
        self.centerY = (top + bottom) // 2

def find_color_pair():
    """Yellow and blue blobs side by side, merged into one box, for when the code drops out."""
    yellow = None
    blue = None
    for obj in ai_vision.take_snapshot(AiVision.ALL_COLORS, VISION_MAX_OBJECTS):
        if obj.width < VISION_MIN_WIDTH or obj.height < VISION_MIN_HEIGHT:
            continue
        if obj.id == YELLOW_CONE_ID and (yellow is None or obj.width * obj.height > yellow.width * yellow.height):
            yellow = obj
        elif obj.id == BLUE_CONE_ID and (blue is None or obj.width * obj.height > blue.width * blue.height):
            blue = obj
    if yellow is None or blue is None:
        return None
    gap = max(yellow.width, yellow.height, blue.width, blue.height)
    if abs(yellow.centerX - blue.centerX) > gap or abs(yellow.centerY - blue.centerY) > gap:
        return None
    left = min(yellow.centerX - yellow.width // 2, blue.centerX - blue.width // 2)
    right = max(yellow.centerX + yellow.width // 2, blue.centerX + blue.width // 2)
    top = min(yellow.centerY - yellow.height // 2, blue.centerY - blue.height // 2)
    bottom = max(yellow.centerY + yellow.height // 2, blue.centerY + blue.height // 2)
    return ConeBox(left, top, right, bottom)

def find_color(color_id):
    """Return the largest visible object with the requested colour id."""
    largest = None
    largest_area = 0

    for obj in ai_vision.take_snapshot(AiVision.ALL_COLORS, VISION_MAX_OBJECTS):
        if obj.id != color_id:
            continue
        if obj.width < VISION_MIN_WIDTH or obj.height < VISION_MIN_HEIGHT:
            continue
        area = obj.width * obj.height
        if area > largest_area:
            largest = obj
            largest_area = area

    return largest

def search_color_circle():
    """Find, center on, and approach the cone color code."""
    left_motor.set_stopping(BRAKE)
    right_motor.set_stopping(BRAKE)
    brain.screen.clear_screen()
    brain.screen.set_cursor(1, 1)
    brain.screen.print("searching for cone")

    hits = 0
    while True:
        target = find_cone()
        if target is not None:
            hits = hits + 1
        else:
            hits = 0

        if target is not None and hits >= VISION_CONFIRM_FRAMES:
            break

        left_motor.spin(FORWARD, SEARCH_INNER_POWER, PERCENT)
        right_motor.spin(FORWARD, SEARCH_OUTER_POWER, PERCENT)
        wait(VISION_LOOP_MS, MSEC)

    brain.screen.clear_screen()
    brain.screen.set_cursor(1, 1)
    brain.screen.print("centering on cone")

    while True:
        target = find_cone()
        if target is None:
            left_motor.stop()
            right_motor.stop()
            brain.screen.set_cursor(3, 1)
            brain.screen.print("cone lost - searching")
            reacquire_cone()
            continue

        if target.width >= APPROACH_TARGET_WIDTH:
            break

        error = target.centerX - VISION_CENTER_X
        steer = steer_power(error)
        if abs(error) > APPROACH_DRIVE_ERROR:
            forward = 0
        else:
            closeness = min(1.0, target.width / float(APPROACH_TARGET_WIDTH))
            forward = APPROACH_FORWARD_POWER - (APPROACH_FORWARD_POWER - APPROACH_MIN_FORWARD) * closeness
        left_motor.spin(FORWARD, forward + steer, PERCENT)
        right_motor.spin(FORWARD, forward - steer, PERCENT)
        wait(VISION_LOOP_MS, MSEC)

    left_motor.stop()
    right_motor.stop()

def steer_power(error):
    """Proportional turn power for a centerX error, with a floor to beat friction."""
    if abs(error) <= APPROACH_CENTER_TOLERANCE:
        return 0
    power = APPROACH_STEER_KP * error
    if abs(power) < APPROACH_MIN_TURN:
        power = APPROACH_MIN_TURN if error > 0 else -APPROACH_MIN_TURN
    return max(-APPROACH_MAX_TURN, min(APPROACH_MAX_TURN, power))

def reacquire_cone():
    """Circle until the cone is seen for several frames in a row."""
    hits = 0
    while hits < VISION_CONFIRM_FRAMES:
        if find_cone() is not None:
            hits = hits + 1
        else:
            hits = 0
        left_motor.spin(FORWARD, SEARCH_INNER_POWER, PERCENT)
        right_motor.spin(FORWARD, SEARCH_OUTER_POWER, PERCENT)
        wait(VISION_LOOP_MS, MSEC)

def cone_detector():
    """Watch continuously and announce the cone each time it comes into view."""
    brain.screen.clear_screen()
    brain.screen.set_cursor(1, 1)
    brain.screen.print("AI VISION  --  watching for cone")

    visible = False
    hits = 0
    misses = 0

    while True:
        cone = find_cone()

        if cone is not None:
            hits = hits + 1
            misses = 0
        else:
            misses = misses + 1
            hits = 0

        if cone is not None and not visible and hits >= VISION_CONFIRM_FRAMES:
            visible = True
            print("cone identified")
            brain.screen.clear_line(3)
            brain.screen.set_cursor(3, 1)
            brain.screen.print("cone identified")
            brain.screen.clear_line(4)
